import { defineProvider, presets } from "@shared/core";

/**
 * TikHub (tikhub.io) - one REST API over the public data of TikTok,
 * Douyin, Xiaohongshu, Weibo, WeChat, Bilibili, Kuaishou, Instagram,
 * YouTube, Reddit, Threads, Zhihu and more. Every endpoint is a synchronous
 * JSON call against `https://api.tikhub.io/api/v1/...`, auth
 * `Authorization: Bearer <token>`.
 *
 * The endpoints are GENERATED by `deno task tikhub:scaffold`: one folder per
 * endpoint Monid sells, inputs mirrored from TikHub's OpenAPI spec, the
 * per-call price from Monid's listing. TikHub bills a flat USD amount per
 * successful request (stated per endpoint in its docs), so the pool is US
 * dollars and each endpoint's PER_CALL amount IS its price. Responses carry
 * no cost receipt, so there is no consolidate: the derived fold is the bill.
 */
export default defineProvider({
    name: "tikhub",
    meta: {
        displayName: "TikHub",
        summary: "Social media data across TikTok, Douyin, Xiaohongshu, " +
            "Weibo, WeChat, Instagram, YouTube and more.",
        description: "Public social media data through one API - " +
            "profiles, posts, videos, comments, search, trending lists and " +
            "creator analytics across TikTok (including TikTok Shop and " +
            "Ads), Douyin, Xiaohongshu, Weibo, WeChat Official Accounts " +
            "and Channels, Bilibili, Kuaishou, Toutiao, Xigua, Pipixia, " +
            "Lemon8, Zhihu, Instagram, YouTube, Reddit, Threads, LinkedIn " +
            "and Telegram. Each endpoint mirrors one TikHub route and " +
            "returns TikHub's envelope with the platform data under `data`.",
        homepageUrl: "https://www.tikhub.io",
        docsUrl: "https://api.tikhub.io/docs",
        notes: [
            "The platform payload is under `data`; its shape is the " +
            "platform's own and varies per endpoint.",
            "TikHub recommends a 30-60 s timeout; slow upstream platforms " +
            "can make a call take most of it.",
        ],
    },
    auth: { inject: presets.auth.bearer() },
    request: { baseUrl: "https://api.tikhub.io" },
    timeouts: { requestMs: 60_000, runMs: 65_000 },
    usage: {
        credits: { default: { label: "US dollars" } },
    },
    output: {
        /** TikHub errors are FastAPI `{detail}` bodies: `{detail: {code,
         *  message, ...}}` for TikHub's own failures, `{detail: [{loc, msg,
         *  type}]}` for input validation (422). Vendor non-2xx is DATA - the
         *  engine zero-bills it. */
        fromError: ({ data, utils }) => {
            const detail = utils.json.optionalGet(data.output, "$.detail");
            const texts = [
                utils.json.optionalGet(data.output, "$.detail.message"),
                utils.json.optionalGet(data.output, "$.detail[0].msg"),
                typeof detail === "string" ? detail : undefined,
                utils.json.optionalGet(data.output, "$.message"),
            ];
            const text = texts.find((v) => typeof v === "string" && v !== "");
            return {
                message: typeof text === "string" ? text : "TikHub API error",
                raw: data.output,
            };
        },
    },
});
